tests.pseudocode:
std = set(run('go list std').lines); bad = []
for f in glob('issuex/**/*.go'):
  for imp in parse_file(f).Imports:
    p = unquote(imp.Path.Value)
    if p not in std: bad.append((f, p))
    assert p != 'os/exec'
assert bad == []; assert grep('issuex/**/*.go', 'ForkExec|syscall.Exec|exec.Command') == []

io_methods = all methods except {Forge, Authenticated, Close}; assert len(io_methods) == 20
for m in io_methods: assert m.Type.In(0) == reflect.TypeOf((*context.Context)(nil)).Elem()
for m in all_methods:
  for i in range(m.Type.NumOut()):
    o = m.Type.Out(i)
    if o == error_type: continue
    assert o.Kind() not in (reflect.Ptr, reflect.Map)
    if o.Kind() == reflect.Slice: assert o.Elem().Kind() == reflect.Struct
    else: assert o.Kind() in (reflect.Struct, reflect.String, reflect.Int, reflect.Bool)

for c in [NewNull(), must(New(Options{Forge: ForgeNone}))]:
  ref = IssueRef{Repo: Repo{'o','r'}, Number: 42}
  before, err0 = c.GetIssue(ctx, ref); assert err0 == nil
  for i in 1..3: assert c.Close() == nil
  after, err1 = c.GetIssue(ctx, ref)
  assert after == before and err1 == nil

want = {'Repo': [('Owner','string'),('Name','string')], 'MergeResult': [('Merged','bool'),('SHA','string'),('Message','string')], ...}
assert len(want) == 22
ptrs = []
for name, fields in want:
  t = type_of(name); assert field_list(t) == fields
  for f in t.Fields: assert string(f.Tag) == '' ; assert f.Type.Kind() != reflect.Map
    if f.Type.Kind() == reflect.Ptr: ptrs.append(name + '.' + f.Name)
assert ptrs == ['IssueUpdate.Title','IssueUpdate.Body']

for f in [ForgeGitHub, ForgeGitLab]:
  c, err = New(Options{Forge: f})
  assert c == nil and errors.Is(err, ErrForgeUnsupported)
  assert string(f) in err.Error() and strings.HasPrefix(err.Error(), 'issuex: ')
for file in glob('issuex/**/*.go'): assert 'panic("not implemented")' not in read(file)

