for h in [{}, {ra:'', reset:''}, {ra:'soon'}, {reset:'later'}, {ra:'-5'}, {ra:'-5', reset:'-1'}]:
  for status, rem in [(429, ''), (403, '0')]:
    e = &HTTPError{Status: status, RateLimitRemaining: rem, RetryAfterHeader: h.ra, RateLimitReset: h.reset}
    d, ok = e.RetryAfter()
    assert d == 0 and ok == false
    assert errors.Is(e, ErrRateLimited)

for status in 100..599:
  for ra in ['', '0', '30', 'x']: for reset in ['', past, future, 'x']: for rem in ['', '0', '57']:
    e = &HTTPError{Status:status, RetryAfterHeader:ra, RateLimitReset:reset, RateLimitRemaining:rem, Method:'GET', Path:'/p'}
    limited = status == 429 or (status == 403 and rem == '0')
    d1, ok1 = e.RetryAfter(); d2, ok2 = e.RetryAfter()
    assert (d1, ok1) == (d2, ok2)
    if not limited: assert (d1, ok1) == (0, false)
    assert e.Error() == e.Error() and e.Unwrap() == e.Unwrap()
assert tripper.calls == 0

